def parse_frontmatter(text: str) -> dict[str, object] | None:
    """Parse a YAML-subset frontmatter block at the top of a markdown string.

    Returns the parsed key/value mapping, or None when no frontmatter is present
    or the closing `---` is missing.

    Supports:
    - bare strings: `key: value`
    - single-quoted: `key: 'value'`
    - double-quoted: `key: "value"`
    - lists: `key: [a, b, "c"]`
    - inline comment lines beginning with `#`
    """
    if not text.startswith("---\n"):
        return None
    # Closing delimiter: "\n---\n" inside the file, or "\n---" at EOF.
    end = text.find("\n---\n", 4)
    if end == -1 and text.endswith("\n---"):
        end = len(text) - 4
    if end == -1:
        return None
    block = text[4:end].strip("\n")
    result: dict[str, object] = {}
    for raw in block.splitlines():
        # Anchor at column 0: skip comments + indented lines.
        if not raw or raw.startswith("#") or raw[0] in (" ", "\t"):
            continue
        if ":" not in raw:
            continue
        key, _, value = raw.partition(":")
        key = key.strip()
        if not key:
            continue
        value = value.strip()
        if value.startswith("[") and value.endswith("]"):
            inner = value[1:-1].strip()
            result[key] = (
                [item.strip().strip("'\"") for item in inner.split(",") if item.strip()]
                if inner
                else []
            )
        elif (value.startswith('"') and value.endswith('"')) or (
            value.startswith("'") and value.endswith("'")
        ):
            result[key] = value[1:-1]
        else:
            result[key] = value
    return result

# 附录 C：智能体框架选型检查

框架通常封装模型调用、工具调度、状态、图/循环编排、持久化与追踪。先实现能描述清楚的最小流程，再判断哪些能力值得交给框架；框架名字和下载量不能保证适合任务。

| 需求 | 应检查的能力 | 最小验收 |
|---|---|---|
| 固定流程 | 条件分支、类型约束 | 错误分支不继续执行 |
| 长任务 | 检查点、恢复、任务状态 | 中断后从已确认位置继续 |
| 工具调用 | 参数校验、权限、结果关联 | 错参数被拦截且可定位 |
| 多 Agent | 隔离、消息、合并 | 不覆盖彼此结果 |
| 生产维护 | 日志、版本、导出、测试 | 能重放一次失败 |

选型试验只需一个真实小任务：两步处理、一次工具失败、一次人工补充。比较自写简单程序与候选框架在可解释性、代码量、状态恢复、成本和依赖复杂度上的差异。若没有实际收益，简单程序可以是最终方案。

